-- Everything is a "Modo" now (product owner's decision): one list, one choice.
-- Scenes shown as modes get a tagline; Black Friday becomes the all-year "Compras"; new "Aniversário".
alter table public.scenes add column tagline text;
grant select (tagline) on public.scenes to anon, authenticated;

-- The person the pet wishes a happy birthday to (optional, typed by the owner; only for the line).
alter table public.generations add column recipient_name text check (recipient_name is null or char_length(recipient_name) between 1 and 20);

update public.scenes set tagline = 'Preguiça ao sol. Areia no pelo, nunca.' where id = 'pt-praia';
update public.scenes set tagline = 'Uma descida e já se acha profissional.' where id = 'pt-snowboard';
insert into public.scenes (id, language, name, tagline, image_prompt, voice_prompt, kind, category, markets, exaggerated, faithful, sort_order, active) values ('pt-compras', 'pt-PT', 'Compras', 'Cartão na pata. A conta que se aguente.', 'Place the pet in a bright, colourful shop on a huge shopping spree, next to a shop counter with a card payment terminal. The pet holds a plain shiny bank card (no logos, no numbers) in one front paw, about to tap it on the terminal, while an endless paper receipt curls out of the terminal and piles up on the floor. Around it: colourful shopping bags with bright red sale tags and a few {currency} banknotes (recognisable by their colours and currency sign only, with no portrait or face printed on them) flying out of an open wallet. No brand names, logos or readable text anywhere.', 'A pet on a huge shopping spree with the human''s bank card: taps it on every terminal, the account is emptying fast and it does not care, the receipt is longer than its tail, and it only buys treats and boxes. Jokes about the card, the payments going through and the money leaving the account.', 'place', null, null, false, true, 5, true);
insert into public.scenes (id, language, name, tagline, image_prompt, voice_prompt, kind, category, markets, exaggerated, faithful, sort_order, active) values ('pt-aniversario', 'pt-PT', 'Aniversário', 'Dá os parabéns. E rouba o bolo.', 'Place the pet at a joyful birthday party in a bright living room: it wears a colourful party hat and sits proudly next to a big birthday cake with lit candles, surrounded by balloons in many colours (pink, blue, yellow and green), paper streamers and a few wrapped presents. No readable text and no banners with letters.', 'A pet wishing a happy birthday to someone it loves: warm, cheeky and funny. The line is a birthday wish in the pet''s own way (it congratulates the birthday person, but is mostly interested in the cake, the candles or the wrapping paper).', 'place', null, null, false, false, 6, true);
